/**
 * 섹션 2 · 유닛 2 — 지금 몇 시예요?
 * 출처: 서울대 한국어 1B 10과
 *
 * 배우는 것
 *   시간대       새벽·아침·낮·저녁·밤·오전·오후
 *   동사 2       일어나다·세수하다·샤워하다·빨래하다·청소하다·요리하다
 *               운전하다·전화하다·컴퓨터를 하다·회의하다·버스를 기다리다·버스를 타다
 *   시각         N시 N분 · 반 · 쯤 · 몇 시에
 *   문법         N부터 N까지  ·  V-아서/어서  ·  V-(으)ㄹ 거예요
 *
 * 이 유닛의 함정
 *   1. 두 가지 수     시는 고유어(한 시·두 시), 분은 한자어(십 분·이십 분)
 *   2. 한·두·세·네     시 앞에서는 하나·둘·셋·넷이 아니라 한·두·세·네
 *   3. 부터 ↔ 까지     시작은 부터, 끝은 까지. 뒤집으면 뜻이 반대가 된다
 *   4. 아서/어서       모음 규칙은 -아요/어요와 같고 하다는 해서
 *   5. 받침 → 거예요   가다→갈 거예요(ㄹ) · 먹다→먹을 거예요(을)
 */

