      en: '-아서/어서 means "do A first, then B". It attaches by the same rule as -아요/어요: ㅏ or ㅗ takes 아서, others 어서, and 하다 becomes 해서.',
      ru: '-아서/어서 значит «сначала A, потом B». Правило то же, что у -아요/어요: ㅏ и ㅗ — 아서, остальные — 어서, 하다 — 해서.',
